//@ args = '--with my:inline/foo=alien.h'

#include <string.h>
#include "runner.h"

void exports_runner_run() {
    my_inline_bar_msg_t msg;
    my_inline_foo_string_set(&msg.field, "hello");
    my_inline_bar_bar(&msg);
}

// normally this comes from a separate compilation unit of types generated by wit-bindgen, e.g. libalien.a
void my_inline_foo_string_set(my_inline_foo_string_t *ret, char const* s) {
  ret->ptr = (uint8_t*) s;
  ret->len = strlen(s);
}
